using Forjix.Domain.Entities.Identity;
using Forjix.Domain.Enums;
namespace Forjix.Domain.Entities.Purchases;

public sealed class Purchase { public Guid Id { get; set; } public required string Number { get; set; } public Guid SupplierId { get; set; } public PurchaseStatus Status { get; private set; } = PurchaseStatus.Pending; public decimal Total { get; set; } public string? Notes { get; set; } public Guid UserId { get; set; } public DateTimeOffset CreatedAt { get; set; } public DateTimeOffset? ReceivedAt { get; private set; } public DateTimeOffset? CancelledAt { get; private set; } public byte[] RowVersion { get; set; } = []; public Supplier Supplier { get; set; } = null!; public User User { get; set; } = null!; public ICollection<PurchaseItem> Items { get; set; } = []; public void Receive(DateTimeOffset now) { if (Status != PurchaseStatus.Pending) throw new InvalidOperationException(); Status = PurchaseStatus.Received; ReceivedAt = now; } public void Cancel(DateTimeOffset now) { if (Status != PurchaseStatus.Pending) throw new InvalidOperationException(); Status = PurchaseStatus.Cancelled; CancelledAt = now; } }
